mapper.update:
update setmeal
name = #{name}, price = #{price}, status = #{status}, category_id = #{categoryId}, description = #{description}, image = #{image}, update_time = #{updateTime}, update_user = #{updateUser}
where id = #{id}

mapper.select:
select * from setmeal

    and name like '%${name}%'
    and category_id = #{categoryId}
    and status = #{status}

order by update_time desc
